const cfg = $input.first().json;
const LOOKBACK_HOURS = 48;
const now = new Date();
const startUnix = Math.floor((now.getTime() - LOOKBACK_HOURS * 3600 * 1000) / 1000);
return [{ json: {
  zendesk_domain: cfg.zendesk_domain,
  automation_agent_id: cfg.automation_agent_id == null ? null : String(cfg.automation_agent_id),
  high_risk_check_enabled: cfg.high_risk_check_enabled,
  high_risk_enforce: cfg.high_risk_enforce,
  start_unix: startUnix,
  now_iso: now.toISOString(),
  lookback_hours: LOOKBACK_HOURS
} }];

const w = $('Build window').first().json;

const TAG_TIER = {
  'high-risk-safety-critical': 'C',
  'high-risk-legal-financial': 'A',
  'high-risk-conduct': 'B'
};
const TIER_LABEL = { A: 'Commercial threat', B: 'Hostility / repeat / account', C: 'Safety / duty of care' };
const TIER_QUEUE = { A: 'Priority', B: 'Standard', C: 'safety-review' };

const byId = new Map();
for (const item of $input.all()) {
  const arr = (item.json && Array.isArray(item.json.tickets)) ? item.json.tickets : [];
  for (const t of arr) byId.set(String(t.id), t);
}
const all = Array.from(byId.values());

function hrTags(t) {
  const tags = Array.isArray(t.tags) ? t.tags : [];
  return tags.filter(tag => TAG_TIER[tag]);
}

const nowMs = Date.parse(w.now_iso);
const capMs = nowMs - 24 * 3600 * 1000;

const flaggedAll = all.filter(t => hrTags(t).length > 0);
flaggedAll.sort((a, b) => Date.parse(a.created_at) - Date.parse(b.created_at));
const firstFlagged = flaggedAll.length ? flaggedAll[0] : null;

let windowStartMs;
let windowBasis;
if (!firstFlagged) {
  windowStartMs = capMs;
  windowBasis = 'no_flagged_ticket_found_fallback_last_24h';
} else if (Date.parse(firstFlagged.created_at) < capMs) {
  windowStartMs = capMs;
  windowBasis = 'capped_at_last_24h';
} else {
  windowStartMs = Date.parse(firstFlagged.created_at);
  windowBasis = 'first_flagged_ticket';
}

const inWindow = all.filter(t => {
  const c = Date.parse(t.created_at);
  return c >= windowStartMs && c <= nowMs;
});
const flagged = inWindow.filter(t => hrTags(t).length > 0);

function tally(list, fn) {
  const m = {};
  for (const x of list) {
    const k = fn(x);
    if (k === null || k === undefined) continue;
    m[k] = (m[k] || 0) + 1;
  }
  return m;
}

const perTag = {};
for (const tag of Object.keys(TAG_TIER)) perTag[tag] = 0;
let multiTagged = 0;
for (const t of flagged) {
  const hits = hrTags(t);
  if (hits.length > 1) multiTagged++;
  for (const tag of hits) perTag[tag]++;
}

const tagFreq = {};
for (const t of inWindow) {
  for (const tag of (Array.isArray(t.tags) ? t.tags : [])) tagFreq[tag] = (tagFreq[tag] || 0) + 1;
}
const topTags = Object.entries(tagFreq).sort((a, b) => b[1] - a[1]).slice(0, 25).map(e => ({ tag: e[0], count: e[1] }));

function hourKey(iso) { return String(iso).slice(0, 13) + ':00Z'; }

const MAX_DETAIL = 400;
const detail = flagged.slice().sort((a, b) => Date.parse(a.created_at) - Date.parse(b.created_at)).slice(0, MAX_DETAIL).map(t => {
  const hits = hrTags(t);
  const tiers = hits.map(h => TAG_TIER[h]);
  return {
    ticket_id: t.id,
    created_at: t.created_at,
    updated_at: t.updated_at,
    status: t.status,
    channel: (t.via && t.via.channel) ? t.via.channel : null,
    subject: String(t.subject == null ? '' : t.subject).slice(0, 140),
    hr_tags: hits,
    tiers: tiers,
    tier_label: tiers.length ? TIER_LABEL[tiers[0]] : null,
    queue: tiers.length ? TIER_QUEUE[tiers[0]] : null,
    assignee_id: t.assignee_id == null ? null : String(t.assignee_id)
  };
});

const summary = {
  generated_at: w.now_iso,
  project_key: 'personality_prod',
  zendesk_domain: w.zendesk_domain,
  config_high_risk_check_enabled: w.high_risk_check_enabled,
  config_high_risk_enforce: w.high_risk_enforce,
  lookback_hours_pulled: w.lookback_hours,
  tickets_pulled_total: all.length,
  flagged_anywhere_in_pull: flaggedAll.length,
  first_flagged_ticket_id: firstFlagged ? firstFlagged.id : null,
  first_flagged_created_at: firstFlagged ? firstFlagged.created_at : null,
  window_basis: windowBasis,
  window_start: new Date(windowStartMs).toISOString(),
  window_end: w.now_iso,
  window_hours: Math.round(((nowMs - windowStartMs) / 3600000) * 100) / 100,
  tickets_created_in_window: inWindow.length,
  high_risk_in_window: flagged.length,
  high_risk_pct_of_window: inWindow.length ? Math.round((flagged.length / inWindow.length) * 10000) / 100 : 0,
  multi_tag_tickets: multiTagged,
  per_tag: perTag,
  per_tier: {
    A_legal_financial: perTag['high-risk-legal-financial'],
    B_conduct: perTag['high-risk-conduct'],
    C_safety_critical: perTag['high-risk-safety-critical']
  },
  high_risk_status_breakdown: tally(flagged, t => t.status),
  all_status_breakdown: tally(inWindow, t => t.status),
  high_risk_channel_breakdown: tally(flagged, t => (t.via && t.via.channel) ? t.via.channel : 'unknown'),
  all_channel_breakdown: tally(inWindow, t => (t.via && t.via.channel) ? t.via.channel : 'unknown'),
  hourly_all: tally(inWindow, t => hourKey(t.created_at)),
  hourly_high_risk: tally(flagged, t => hourKey(t.created_at)),
  top_tags_in_window: topTags,
  detail_truncated: flagged.length > MAX_DETAIL
};

return [{ json: { summary: summary, high_risk_tickets: detail } }];

const base = $('Analyse tickets').first().json;
const w = $('Build window').first().json;
const agentId = w.automation_agent_id;

const srcItems = $('Split high risk tickets').all();
const responses = $input.all();

function stripQuotes(s) {
  let v = String(s == null ? '' : s).trim();
  if (v.length > 1 && v.charAt(0) === '"' && v.charAt(v.length - 1) === '"') v = v.slice(1, -1);
  return v;
}

function noteFields(body) {
  const lines = String(body).split(String.fromCharCode(10));
  const kv = {};
  const extra = [];
  for (const raw of lines) {
    const line = raw.trim();
    if (line.indexOf('- ') === 0) {
      const rest = line.slice(2);
      const c = rest.indexOf(':');
      if (c > 0) {
        const left = rest.slice(0, c);
        const kw = rest.slice(c + 1).trim();
        const slash = left.indexOf('/');
        if (slash > 0) {
          extra.push({ tier: left.slice(0, slash).trim(), category: left.slice(slash + 1).trim(), keyword: kw });
        }
      }
      continue;
    }
    const ci = line.indexOf(':');
    if (ci > 0) {
      const key = line.slice(0, ci).trim();
      if (!(key in kv)) kv[key] = line.slice(ci + 1).trim();
    }
  }
  const tierRaw = kv['Tier'] || null;
  const phrase = kv['Matched phrase'] ? stripQuotes(kv['Matched phrase']) : null;
  return {
    tier: tierRaw ? tierRaw.split(' - ')[0].trim() : null,
    tier_label: tierRaw ? String(tierRaw.split(' - ')[1] || '').trim() : null,
    category: kv['Category'] || null,
    queue: kv['Queue'] || null,
    tag_applied: kv['Tag applied'] || null,
    primary_match: phrase,
    all_matches: extra,
    match_count: extra.length ? extra.length : (phrase ? 1 : 0)
  };
}

const enriched = [];
for (let i = 0; i < responses.length; i++) {
  const r = responses[i];
  let srcIdx = i;
  const pi = r.pairedItem;
  if (pi != null) {
    if (typeof pi === 'number') srcIdx = pi;
    else if (Array.isArray(pi) && pi.length && typeof pi[0].item === 'number') srcIdx = pi[0].item;
    else if (typeof pi === 'object' && typeof pi.item === 'number') srcIdx = pi.item;
  }
  const src = (srcItems[srcIdx] && srcItems[srcIdx].json) ? srcItems[srcIdx].json : {};
  const comments = (r.json && Array.isArray(r.json.comments)) ? r.json.comments : [];

  let note = null;
  let noteAtMs = null;
  for (const c of comments) {
    const body = String(c.body == null ? '' : c.body);
    if (c.public === false && body.indexOf('matched the high-risk keyword list') !== -1) {
      note = noteFields(body);
      noteAtMs = Date.parse(c.created_at);
    }
  }

  let botPublicReplies = 0;
  let botReplyAfterFlag = false;
  for (const c of comments) {
    if (c.public !== true) continue;
    const author = c.author_id == null ? '' : String(c.author_id);
    if (agentId && author === agentId) {
      botPublicReplies++;
      if (noteAtMs === null || Date.parse(c.created_at) >= noteAtMs) botReplyAfterFlag = true;
    }
  }

  enriched.push({
    ticket_id: src.ticket_id,
    created_at: src.created_at,
    status: src.status,
    channel: src.channel,
    subject: src.subject,
    hr_tags: src.hr_tags,
    comments_fetched: comments.length,
    note_found: note !== null,
    tier: note ? note.tier : ((src.tiers && src.tiers.length) ? src.tiers[0] : null),
    tier_label: note ? note.tier_label : src.tier_label,
    category: note ? note.category : null,
    queue: note ? note.queue : src.queue,
    primary_match: note ? note.primary_match : null,
    match_count: note ? note.match_count : null,
    all_matches: note ? note.all_matches : [],
    bot_public_replies: botPublicReplies,
    bot_replied_after_flag: botReplyAfterFlag
  });
}

function tallyMulti(list, fn) {
  const m = {};
  for (const x of list) {
    const ks = fn(x);
    const arr = Array.isArray(ks) ? ks : [ks];
    for (const k of arr) {
      if (k === null || k === undefined || k === '') continue;
      m[k] = (m[k] || 0) + 1;
    }
  }
  return m;
}

function sortDesc(obj, limit) {
  return Object.entries(obj).sort((a, b) => b[1] - a[1]).slice(0, limit || 50).map(e => ({ key: e[0], count: e[1] }));
}

const keywordFreq = tallyMulti(enriched, e => (e.all_matches && e.all_matches.length)
  ? e.all_matches.map(m => m.tier + ' | ' + m.category + ' | ' + m.keyword)
  : (e.primary_match ? [(e.tier || '?') + ' | ' + (e.category || '?') + ' | ' + e.primary_match] : []));

const primaryKeywordFreq = tallyMulti(enriched, e => e.primary_match);
const categoryFreq = tallyMulti(enriched, e => e.category);
const queueFreq = tallyMulti(enriched, e => e.queue);

const multiMatch = enriched.filter(e => (e.match_count || 0) > 1).length;
const notesMissing = enriched.filter(e => !e.note_found).length;
const botRepliedAfterFlag = enriched.filter(e => e.bot_replied_after_flag).length;
const anyBotReply = enriched.filter(e => e.bot_public_replies > 0).length;

return [{ json: {
  summary: base.summary,
  keyword_analysis: {
    flagged_tickets_inspected: enriched.length,
    internal_note_found: enriched.length - notesMissing,
    internal_note_missing: notesMissing,
    tickets_matching_more_than_one_keyword: multiMatch,
    by_category: sortDesc(categoryFreq),
    by_queue: sortDesc(queueFreq),
    by_primary_keyword: sortDesc(primaryKeywordFreq, 60),
    by_keyword_all_matches: sortDesc(keywordFreq, 80)
  },
  enforcement_impact: {
    note: 'With high_risk_enforce OFF the bot still replies. These counts show what enforce ON would have pulled out of automation.',
    flagged_tickets_with_a_public_bot_reply: anyBotReply,
    flagged_tickets_where_bot_replied_after_the_flag: botRepliedAfterFlag
  },
  flagged_tickets: enriched
} }];
